  ($i697g$ChIJI-SCoXWLa4oRXZqSiVww0jY$i697g$, $i697p$organisation/ChIJI-SCoXWLa4oRXZqSiVww0jY/6.jpg$i697p$, 6),
  ($i698g$ChIJI-SCoXWLa4oRXZqSiVww0jY$i698g$, $i698p$organisation/ChIJI-SCoXWLa4oRXZqSiVww0jY/7.jpg$i698p$, 7),
  ($i699g$ChIJI-SCoXWLa4oRXZqSiVww0jY$i699g$, $i699p$organisation/ChIJI-SCoXWLa4oRXZqSiVww0jY/8.jpg$i699p$, 8),
  ($i700g$ChIJI-SCoXWLa4oRXZqSiVww0jY$i700g$, $i700p$organisation/ChIJI-SCoXWLa4oRXZqSiVww0jY/9.jpg$i700p$, 9),
  ($i701g$ChIJI-SCoXWLa4oRXZqSiVww0jY$i701g$, $i701p$organisation/ChIJI-SCoXWLa4oRXZqSiVww0jY/10.jpg$i701p$, 10)
) as v(google_place_id, storage_path, sort_order)
join public.craftsmans as craftsman
  on craftsman.google_place_id = v.google_place_id
where not exists (
  select 1
  from public.craftsmans_images existing
  where existing.craftsman_id = craftsman.id
    and existing.sort_order = v.sort_order
);
